(() => {
  "use strict";

  const landingScreen = document.querySelector("#landing-screen");
  const loadingScreen = document.querySelector("#loading-screen");
  const documentScreen = document.querySelector("#document-screen");
  const enterButton = document.querySelector("#enter-button");
  const asciiLoader = document.querySelector("#ascii-loader");
  const asciiRows = [...asciiLoader.querySelectorAll("span")];
  const pdfScroll = document.querySelector("#pdf-scroll");
  const pdfPages = document.querySelector("#pdf-pages");

  const PDF_URL = "https://docs.google.com/document/d/1HqrQDeOyaaiQIRB-m9CB04m_nCMFdTwE/export?format=pdf";
  const PDF_JS_URL = "https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.min.mjs";
  const PDF_WORKER_URL = "https://cdn.jsdelivr.net/npm/pdfjs-dist@4.10.38/build/pdf.worker.min.mjs";
  const PAGE_BACKGROUND = "#284E12";
  const PAGE_WIDTH = 816;
  const INLINE_PDF_BASE64 = "";

  const prefersReducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  const ASCII_CHARACTERS = "!@#$%^&*()_+-=[]{}|;:,.<>?/0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz";
  const ASCII_ROW_SIZE = 10;
  const ASCII_ACTIVE_CHARACTERS = 4;
  const minimumLoadingTime = prefersReducedMotion ? 450 : 2200;

  let loaderTimer = null;
  let loaderPosition = -ASCII_ACTIVE_CHARACTERS;
  let loadingStartedAt = 0;
  let documentRequested = false;
  let documentRevealed = false;

  function animateLoader() {
    const drawLoader = () => {
      asciiRows.forEach((row, rowIndex) => {
        const characters = Array.from({ length: ASCII_ROW_SIZE }, (_, columnIndex) => {
          const start = loaderPosition - rowIndex;
          const active = columnIndex >= start && columnIndex < start + ASCII_ACTIVE_CHARACTERS;

          if (!active) return "-";
          return ASCII_CHARACTERS[Math.floor(Math.random() * ASCII_CHARACTERS.length)];
        });

        row.textContent = characters.join("");
      });

      loaderPosition += 1;
      if (loaderPosition > ASCII_ROW_SIZE + asciiRows.length) {
        loaderPosition = -ASCII_ACTIVE_CHARACTERS;
      }
    };

    drawLoader();
    if (prefersReducedMotion) return;

    loaderTimer = window.setInterval(drawLoader, 90);
  }

  function showLoadingScreen() {
    landingScreen.classList.add("is-leaving");

    window.setTimeout(() => {
      landingScreen.hidden = true;
      landingScreen.setAttribute("aria-hidden", "true");

      loadingScreen.hidden = false;
      loadingScreen.setAttribute("aria-hidden", "false");
      window.requestAnimationFrame(() => loadingScreen.classList.add("is-visible"));
    }, prefersReducedMotion ? 0 : 280);
  }

  function revealDocument() {
    if (documentRevealed) return;
    documentRevealed = true;
    window.clearInterval(loaderTimer);

    const elapsed = performance.now() - loadingStartedAt;
    const delay = Math.max(0, minimumLoadingTime - elapsed);

    window.setTimeout(() => {
      loadingScreen.classList.add("is-leaving");

      window.setTimeout(() => {
        loadingScreen.hidden = true;
        loadingScreen.setAttribute("aria-hidden", "true");

        documentScreen.hidden = false;
        documentScreen.setAttribute("aria-hidden", "false");
        pdfScroll.focus({ preventScroll: true });
      }, prefersReducedMotion ? 0 : 300);
    }, delay);
  }

  async function renderDocument() {
    try {
      const pdfjs = await import(PDF_JS_URL);
      pdfjs.GlobalWorkerOptions.workerSrc = PDF_WORKER_URL;

      const pdfSource = window.location.protocol === "file:"
        ? { data: Uint8Array.from(window.atob(INLINE_PDF_BASE64), character => character.charCodeAt(0)) }
        : { url: PDF_URL };
      const loadingTask = pdfjs.getDocument(pdfSource);
      const documentPdf = await loadingTask.promise;
      const outputScale = Math.min(window.devicePixelRatio || 1, 2);

      for (let pageNumber = 1; pageNumber <= documentPdf.numPages; pageNumber += 1) {
        const page = await documentPdf.getPage(pageNumber);
        const unscaledViewport = page.getViewport({ scale: 1 });
        const cssScale = PAGE_WIDTH / unscaledViewport.width;
        const cssViewport = page.getViewport({ scale: cssScale });
        const renderViewport = page.getViewport({ scale: cssScale * outputScale });
        const pageElement = document.createElement("section");
        const canvas = document.createElement("canvas");
        const context = canvas.getContext("2d", { alpha: false });

        pageElement.className = "pdf-page";
        pageElement.style.aspectRatio = `${cssViewport.width} / ${cssViewport.height}`;
        pageElement.setAttribute("aria-label", `Page ${pageNumber} of ${documentPdf.numPages}`);

        canvas.className = "pdf-page-canvas";
        canvas.width = Math.ceil(renderViewport.width);
        canvas.height = Math.ceil(renderViewport.height);

        context.fillStyle = PAGE_BACKGROUND;
        context.fillRect(0, 0, canvas.width, canvas.height);

        await page.render({
          canvasContext: context,
          viewport: renderViewport,
          background: PAGE_BACKGROUND
        }).promise;

        pageElement.appendChild(canvas);

        const annotations = await page.getAnnotations({ intent: "display" });
        annotations.forEach(annotation => {
          const url = annotation.url || annotation.unsafeUrl;
          if (annotation.subtype !== "Link" || !url || !annotation.rect) return;

          const [x1, y1, x2, y2] = cssViewport.convertToViewportRectangle(annotation.rect);
          const link = document.createElement("a");
          const left = Math.min(x1, x2);
          const top = Math.min(y1, y2);
          const width = Math.abs(x2 - x1);
          const height = Math.abs(y2 - y1);

          link.className = "pdf-link";
          link.href = url;
          link.target = "_blank";
          link.rel = "noopener noreferrer";
          link.textContent = annotation.title || "Open document link";
          link.setAttribute("aria-label", annotation.title || "Open document link");
          link.style.left = `${(left / cssViewport.width) * 100}%`;
          link.style.top = `${(top / cssViewport.height) * 100}%`;
          link.style.width = `${(width / cssViewport.width) * 100}%`;
          link.style.height = `${(height / cssViewport.height) * 100}%`;
          pageElement.appendChild(link);
        });

        pdfPages.appendChild(pageElement);
        page.cleanup();

        /* Let visitors start reading as soon as the first page is ready. The
           remaining pages continue rendering below it in the background. */
        if (pageNumber === 1) revealDocument();
      }

      revealDocument();
    } catch (error) {
      console.error("The document could not be rendered.", error);
      asciiLoader.textContent = "!";
      asciiLoader.setAttribute("aria-hidden", "false");
      loadingScreen.querySelector("p").textContent = "the document could not load";
    }
  }

  function requestDocument() {
    if (documentRequested) return;
    documentRequested = true;
    loadingStartedAt = performance.now();

    showLoadingScreen();
    animateLoader();
    renderDocument();
  }

  enterButton.addEventListener("click", requestDocument);
})();
